e665bbc607c6c313cd578a089236","defaultExpressions":"false, false"},{"name":"native_salary_context_v1","signature":"public.native_salary_context_v1(jsonb)","argNames":["p"],"result":"jsonb","language":"plpgsql","defaults":0,"config":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"runtime":false,"volatility":"v","bodySha256":"7aad8fc0ecba5ccd2045746b36671104e1911d0783cdf611f6a66c99949ec5de","definitionSha256":"b0daea71e04b25bde311c62bf81d755a73e4281018f2b2fc2ccf289dbe3edf18","defaultExpressions":""},{"name":"native_salary_scope_v1","signature":"public.native_salary_scope_v1(jsonb)","argNames":["ctx"],"result":"text","language":"sql","defaults":0,"config":["search_path=pg_catalog, public, pg_temp"],"runtime":false,"volatility":"i","bodySha256":"36fa43fd409b9785b80600bb0f6257aea65b9ace313a0d11db528e9b685b7253","definitionSha256":"6afd01a45d6f287124774ef1d45e745ec20f6f436a69f9670f3ac95b1dcf67d6","defaultExpressions":""},{"name":"native_salary_administrative_context_v1","signature":"public.native_salary_administrative_context_v1(jsonb)","argNames":["p"],"result":"jsonb","language":"plpgsql","defaults":0,"config":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"runtime":false,"volatility":"v","bodySha256":"346e45cc443193a34b8f000d988cd8e5b4356ec961173a82df91350fd0159451","definitionSha256":"ab36341f912d6d5601a4a72dc4bfbd33418a54436eee1dc91ca7630606ed1489","defaultExpressions":""}]'::jsonb) LOOP
  SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure(expected->>'signature');
  IF actual.oid IS NULL OR actual.proowner<>current_user::regrole OR actual.prokind<>'f' OR NOT actual.prosecdef OR actual.proisstrict OR actual.proretset OR actual.proleakproof OR actual.proparallel<>'u'
   OR actual.provolatile IS DISTINCT FROM(expected->>'volatility')::"char" OR actual.procost<>100 OR actual.prorows<>0 OR actual.prosupport<>0 OR actual.probin IS NOT NULL OR actual.proallargtypes IS NOT NULL OR actual.provariadic<>0 OR actual.prosqlbody IS NOT NULL
   OR actual.prorettype IS DISTINCT FROM to_regtype(expected->>'result') OR actual.prolang IS DISTINCT FROM(SELECT oid FROM pg_language WHERE lanname=expected->>'language') OR actual.pronargdefaults<>(expected->>'defaults')::integer OR actual.proargmodes IS NOT NULL
   OR coalesce(pg_get_expr(actual.proargdefaults,0),'') IS DISTINCT FROM expected->>'defaultExpressions'
   OR coalesce(to_jsonb(actual.proargnames),'null'::jsonb) IS DISTINCT FROM expected->'argNames' OR to_jsonb(actual.proconfig) IS DISTINCT FROM expected->'config'
   OR encode(sha256(convert_to(replace(actual.prosrc,E'\r\n',E'\n'),'UTF8')),'hex')<>expected->>'bodySha256'
   OR(SELECT count(*) FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.proname=expected->>'name')<>1
  THEN RAISE EXCEPTION 'IMPUTATION_AUTHORIZATION_SOURCE_CHANGED';END IF;
  IF EXISTS(SELECT 1 FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))) a WHERE a.grantor<>actual.proowner OR a.privilege_type<>'EXECUTE' OR a.is_grantable OR(a.grantee<>actual.proowner AND NOT((expected->>'runtime')::boolean AND a.grantee=runtime_oid)))
   OR NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))) a WHERE a.grantee=actual.proowner AND a.privilege_type='EXECUTE' AND NOT a.is_grantable)
   OR(expected->>'runtime')::boolean IS DISTINCT FROM EXISTS(SELECT 1 FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))) a WHERE a.grantee=runtime_oid AND a.privilege_type='EXECUTE' AND NOT a.is_grantable)
   OR(SELECT count(*) FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))))<>(CASE WHEN(expected->>'runtime')::boolean THEN 2 ELSE 1 END)
  THEN RAISE EXCEPTION 'IMPUTATION_AUTHORIZATION_ACL_CHANGED';END IF;
 END LOOP;
 FOR prior IN SELECT value FROM jsonb_array_elements(original_functions) LOOP
  SELECT * INTO actual FROM pg_proc WHERE oid=(prior->>'oid')::oid;
  IF actual.oid IS NULL OR(actual.proname IN('own_imputation_bootstrap_v1','own_imputation_source_v1','own_imputation_detail_v1','own_imputation_attempt_v1','own_imputation_command_v1') AND(to_jsonb(actual)-'prosrc') IS DISTINCT FROM(prior-'prosrc'))
   OR(actual.proname NOT IN('own_imputation_bootstrap_v1','own_imputation_source_v1','own_imputation_detail_v1','own_imputation_attempt_v1','own_imputation_command_v1') AND to_jsonb(actual) IS DISTINCT FROM prior)
  THEN RAISE EXCEPTION 'IMPUTATION_AUTHORIZATION_ORIGINAL_METADATA_CHANGED';END IF;
 END LOOP;
 IF(SELECT count(*) FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname LIKE 'own_imputation_%')<>11 THEN RAISE EXCEPTION 'IMPUTATION_AUTHORIZATION_OBJECT_CONFLICT';END IF;
END $imputation_preparation_authorization_205$;
